function validate([time]) {
  if (typeof time !== 'string' || !/^[0-9?]{2}:[0-9?]{2}$/.test(time)) return 'time must look like "hh:mm", using digits or ?.';
  const fits = (pattern, limit) => {
    for (let v = 0; v <= limit; v++) {
      const digits = String(v).padStart(2, '0');
      if ((pattern[0] === '?' || pattern[0] === digits[0]) && (pattern[1] === '?' || pattern[1] === digits[1])) return true;
    }
    return false;
  };
  if (!fits(time.slice(0, 2), 23)) return 'The hour must be able to become a value from 00 to 23.';
  if (!fits(time.slice(3), 59)) return 'The minutes must be able to become a value from 00 to 59.';
  return null;
}

