function countTime(time) {
  let total = 0;
  const fill = (chars, index) => {
    if (index === chars.length) {
      const h = Number(chars[0] + chars[1]);
      const m = Number(chars[3] + chars[4]);
      if (h <= 23 && m <= 59) total++;
      return;
    }
    if (chars[index] !== '?') { fill(chars, index + 1); return; }
    for (let d = 0; d <= 9; d++) {
      const next = chars.slice();
      next[index] = String(d);
      fill(next, index + 1);
    }
  };
  fill(time.split(''), 0);
  return total;
}

